#include "tao_ternary.hpp"
#include <cuda_runtime.h>
#include <cstdio>
namespace tt=tao::ternary;
void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
__global__ void probe(const uint8_t*a,const uint8_t*b,int* products,int8_t* restored,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n){int8_t x=tt::at_unchecked(a,i),y=tt::at_unchecked(b,i);products[i]=int(x)*int(y);restored[i]=tt::subtract(tt::add(x,y),y);}}
int main(){try{int n=100003;std::vector<int8_t>a(n),b(n);for(int i=0;i<n;++i){a[i]=i%3-1;b[i]=(i/3)%3-1;}auto pa=tt::pack(a),pb=tt::pack(b);tt::validate(pa,n);tt::validate(pb,n);uint8_t*da,*db;int*dp;int8_t*dr;ck(cudaMalloc(&da,pa.size()));ck(cudaMalloc(&db,pb.size()));ck(cudaMalloc(&dp,n*sizeof(int)));ck(cudaMalloc(&dr,n));ck(cudaMemcpy(da,pa.data(),pa.size(),cudaMemcpyHostToDevice));ck(cudaMemcpy(db,pb.data(),pb.size(),cudaMemcpyHostToDevice));probe<<<(n+255)/256,256>>>(da,db,dp,dr,n);ck(cudaGetLastError());std::vector<int>products(n);std::vector<int8_t>r(n);ck(cudaMemcpy(products.data(),dp,n*sizeof(int),cudaMemcpyDeviceToHost));ck(cudaMemcpy(r.data(),dr,n,cudaMemcpyDeviceToHost));int64_t sum=0;for(int i=0;i<n;++i){if(products[i]!=int(a[i])*int(b[i])||r[i]!=a[i])throw std::runtime_error("CPU GPU mismatch");sum+=products[i];}if(sum!=tt::dot(pa,pb,n))throw std::runtime_error("wide dot mismatch");ck(cudaFree(da));ck(cudaFree(db));ck(cudaFree(dp));ck(cudaFree(dr));printf("PASS shared CUDA2bit unpack/product/mod3 inverse elements=%d dot=%lld\n",n,(long long)sum);return 0;}catch(const std::exception&e){fprintf(stderr,"FAIL %s\n",e.what());return 1;}}
